// Cloudflare Worker entry: wraps the OpenNext-generated worker to add
// the visitor-country cookie and the daily cron.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}
type Ctx = { waitUntil(p: Promise<unknown>): void };

const COUNTRY_COOKIE = "cah_country"; // keep in sync with src/data/regions.ts

/** Page navigations (not assets/API/Next internals) from visitors without a country cookie. */
function needsCountryCookie(request: Request): boolean {
  if (request.method !== "GET") return false;
  const { pathname } = new URL(request.url);
  if (pathname.startsWith("/_next/") || pathname.startsWith("/api/") || /\.[a-z0-9]+$/i.test(pathname)) return false;
  return !(request.headers.get("cookie") ?? "").includes(`${COUNTRY_COOKIE}=`);
}

export default {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    // Canonical host is www (as on Vercel): 301 the bare domain so search engines see one site.
    const url = new URL(request.url);
    if (url.hostname === "thecahub.com") {
      url.hostname = "www.thecahub.com";
      return Response.redirect(url.toString(), 301);
    }

    const response: Response = await handler.fetch(request, env, ctx);
    if (!needsCountryCookie(request)) return response;

    // Remember the visitor's IP country so the site can suggest their exam body. Never redirects.
    const cf = (request as Request & { cf?: { country?: string } }).cf;
    const country = (cf?.country ?? request.headers.get("cf-ipcountry") ?? "").toUpperCase();
    if (!/^[A-Z]{2}$/.test(country) || country === "XX" || country === "T1") return response;

    const res = new Response(response.body, response);
    res.headers.append("Set-Cookie", `${COUNTRY_COOKIE}=${country}; Path=/; Max-Age=${60 * 60 * 24 * 30}; SameSite=Lax`);
    return res;
  },

  // Replaces the Vercel cron: posts the daily question card to social channels.
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) return;
    const req = new Request("https://www.thecahub.com/api/cron/social", {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from "./.open-next/worker.js";
